			Timestamp:      ts,
			FlagKey:        r.FlagKey,
		}
	)

	flag, err := s.store.GetFlag(ctx, r.FlagKey)
	if err != nil {
		return resp, err
	}

	if !flag.Enabled {
		return resp, errors.ErrInvalidf("flag %q is disabled", r.FlagKey)
	}

	rules, err := s.store.GetEvaluationRules(ctx, r.FlagKey)
	if err != nil {
		return resp, err
	}

	if len(rules) == 0 {
		s.logger.Debug("no rules match")
		return resp, nil
	}

	var lastRank int32

	// rule loop
	for _, rule := range rules {
		if rule.Rank < lastRank {
			return resp, errors.ErrInvalidf("rule rank: %d detected out of order", rule.Rank)
		}

		lastRank = rule.Rank

